"use client"

import animation from "react-useanimations/lib/heart"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Heart" from https://useanimations.com (MIT): https://useanimations.com/icons/heart
export function AnimatedHeart(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="click-toggle"
      {...props}
    />
  )
}
